#include "../config.mcc/mcc_generated_files/system/system.h"
#include "LoRa.h"
#include "drivers/MC33978AES.h"
#include "drivers/tps274c65.h"
#include "modbus/modbus.h"
#include "registers.h"
#include "safety.h"
#include "utils.h"
#include <avr/sleep.h>
#include <avr/wdt.h>
#include <util/delay.h>

volatile bool FsmRun = false;

void ADC0_ConversionDoneCallback(void) {
  uint16_t result = ADC0_ConversionResultGet();
  result = result & 0x0FFF;
  ADC0_ConversionStop();
  __builtin_avr_nop();
}

void RTC_OVF_Callback(void) {
  // Must be run in SR
  // SafetySrLoop();
  FsmRun = true;
}

/*
    Main application
*/
int main(void) {
  // wdt_reset(); // Reset Watchdog before enable it
  SYSTEM_Initialize();

  _delay_ms(1000);

  SPI0_Host_Open(0);

  // Initialisation du module MODBUS UART0
  Modbus_Init();
  MC33978AES_Init();
  tps274c65_init();
  LoRa_Init();

  IO_DO_EN_SetLow();

  // RTC_SetPITIsrCallback(RTC_PTI_Callback); // PTI : 1s
  RTC_SetOVFIsrCallback(RTC_OVF_Callback); // OVF : 10ms

  ADC0_ConversionDoneCallbackRegister(ADC0_ConversionDoneCallback);

  Util_Init();

  while (1) {
    // Pas de sleep_mode() ici : USART1 n'a pas d'interruption RX, le CPU
    // doit rester eveille pour ne pas rater d'octets a 9600 bauds.
    // LoRa_PollRx();

    if (FsmRun) {
      ADC0_ConversionStart();
      wdt_reset(); // WatchDog Reset
      FsmRun = false;
      SafetyMainLoop();
      Modbus_Loop();
      MC33978AES_Loop();
      LoRa_Loop();

      // int32_t adc_res = ADC0_AccumulatedResultGet();
      // Allumage des leds fonctions des entrées pour debug

      global_shadow_ram[REG_OUT_B2] = global_shadow_ram[REG_IN_B1];
      if (global_shadow_ram[REG_IN_B2]) {
        IO_RED_LED_SetHigh();
      } else {
        IO_RED_LED_SetLow();
      }

      if (!DO_EN_IS_ON && Frequency_4Hz) {
        IO_RED_LED_SetHigh();
      } else {
        IO_RED_LED_SetLow();
      }

      global_shadow_ram[REG_OUT_B2] = 0x00; // Par défaut mes leds sont
      // toutes à zero ! global_shadow_ram[REG_OUT_B1] =
      //     0x00; // Par défaut mes relais sont tous à zero !

      if (DO_EN_IS_ON && Safety_ContactActivated()) {
        // Activation du channel 3 : KILLSWITCH OFF ( et AUX, mais c'est juste
        // pour le proto !)
        global_shadow_ram[REG_OUT_B1] |= 0b1100;
        // Led verte correspondante
        global_shadow_ram[REG_OUT_B2] |= 0b1100;
      }

      if (DO_EN_IS_ON && Safety_StartActivated()) {
        global_shadow_ram[REG_OUT_B1] |= 0b0001; // Engine Run
      }

      _registers_buildWorkRegister();
      tps274c65_SendOutputs();
    } else {
      sleep_mode();
      // sleep_cpu();
    }
  }
}